-- Create UserSession table for server-side (cookie) sessions.
-- express-session persists the whole session payload in "data" (JSONB).
-- "id" is the session id generated by express-session (UUID, pluggable).
CREATE TABLE "UserSession" (
    "id" TEXT NOT NULL,
    "data" JSONB NOT NULL DEFAULT '{}'::jsonb,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "expiresAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "UserSession_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "UserSession_expiresAt_idx" ON "UserSession"("expiresAt");

-- Create CacheEntry table: PostgreSQL used as a cache store instead of Redis.
-- Value is JSONB; expired rows are pruned lazily on read and by a scheduled
-- cleanup (see PrismaCacheGateway).
CREATE TABLE "CacheEntry" (
    "key" TEXT NOT NULL,
    "value" JSONB NOT NULL,
    "expiresAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "CacheEntry_pkey" PRIMARY KEY ("key")
);

CREATE INDEX "CacheEntry_expiresAt_idx" ON "CacheEntry"("expiresAt");
